// 1. 소스 노드에서 직접 가져오기
const issueItems = $("연구소백로그 최신목록조회").all();
const vacationItems = $("기술지원캘린더").all();

// 2. 날짜/문자열 기본 유틸
const now = new Date();

// 한국 시간 기준 날짜/시간
const todayKST = new Intl.DateTimeFormat("sv-SE", {
  timeZone: "Asia/Seoul"
}).format(now);

const hourKST = new Intl.DateTimeFormat("en-GB", {
  timeZone: "Asia/Seoul",
  hour: "2-digit",
  hour12: false
}).format(now);

const dateString = new Intl.DateTimeFormat("ko-KR", {
  timeZone: "Asia/Seoul",
  year: "numeric",
  month: "long",
  day: "numeric"
}).format(now);

// 예: 2026-04-28 08시 체크
const checkLabel = `${todayKST} ${hourKST}시 체크`;

const cleanStr = (str) => (str ?? "").toString().normalize("NFC").trim();
const norm = (str) => cleanStr(str).replace(/\s+/g, "").toLowerCase();

// 3. 전체 대상자 명단
const allUsers = [
  { name: "조현재", slackId: "U07K2APTEVD", email: "jyi30@vms-solutions.com" },
  { name: "김민영", slackId: "U07EEDTJZQE", email: "mykim@vms-solutions.com" },
  { name: "김진욱", slackId: "U05DQA2L7JT", email: "jwkim@vms-solutions.com" }
];

// 4. 공통 유틸
function findPropertyKey(props, exactName, partialName) {
  if (!props || typeof props !== "object") return null;

  if (props[exactName]) return exactName;

  const exactNormalized = Object.keys(props).find(
    k => norm(k) === norm(exactName)
  );
  if (exactNormalized) return exactNormalized;

  const partialNormalized = Object.keys(props).find(
    k => norm(k).includes(norm(partialName))
  );

  return partialNormalized || null;
}

function notionPropToString(prop) {
  if (!prop || typeof prop !== "object") return "";

  switch (prop.type) {
    case "status":
      return cleanStr(prop.status?.name);

    case "select":
      return cleanStr(prop.select?.name);

    case "title":
      return cleanStr(
        (prop.title || []).map(t => t.plain_text || t.text?.content || "").join("")
      );

    case "rich_text":
      return cleanStr(
        (prop.rich_text || []).map(t => t.plain_text || t.text?.content || "").join("")
      );

    case "people":
      return cleanStr(
        (prop.people || []).map(p => p.name || p.person?.email || "").join(", ")
      );

    case "date":
      return cleanStr(prop.date?.start);

    case "checkbox":
      return String(!!prop.checkbox);

    case "number":
      return prop.number == null ? "" : String(prop.number);

    case "formula":
      if (!prop.formula) return "";

      if (prop.formula.type === "string") return cleanStr(prop.formula.string);
      if (prop.formula.type === "number") return prop.formula.number == null ? "" : String(prop.formula.number);
      if (prop.formula.type === "boolean") return String(!!prop.formula.boolean);
      if (prop.formula.type === "date") return cleanStr(prop.formula.date?.start);

      return "";

    default:
      return "";
  }
}

function flatValueToString(value) {
  if (value == null) return "";

  if (
    typeof value === "string" ||
    typeof value === "number" ||
    typeof value === "boolean"
  ) {
    return cleanStr(value);
  }

  if (Array.isArray(value)) {
    return cleanStr(
      value.map(v => flatValueToString(v)).filter(Boolean).join(", ")
    );
  }

  if (typeof value === "object") {
    if ("name" in value) return cleanStr(value.name);
    if ("plain_text" in value) return cleanStr(value.plain_text);
    if ("start" in value) return cleanStr(value.start);
    if ("end" in value) return cleanStr(value.end);
  }

  return "";
}

function getFieldValue(page, candidateNames) {
  // A. 원본 Notion API 구조
  if (page.properties && typeof page.properties === "object") {
    for (const name of candidateNames) {
      const propKey = findPropertyKey(page.properties, name, name);
      if (propKey) {
        const v = notionPropToString(page.properties[propKey]);
        if (v) return v;
      }
    }
  }

  // B. 평탄화된 구조
  for (const name of candidateNames) {
    const flatKey = findPropertyKey(page, name, name);
    if (flatKey) {
      const v = flatValueToString(page[flatKey]);
      if (v) return v;
    }
  }

  return "";
}

function getStatus(page) {
  return getFieldValue(page, ["상태", "Status"]);
}

function getIssueType(page) {
  return getFieldValue(page, ["이슈 타입", "Issue Type", "Type"]);
}

function getTitle(page) {
  return getFieldValue(page, ["업무 이름", "Name", "title", "제목"]);
}

function getUrl(page) {
  return cleanStr(page.url || page.URL || page.public_url || "");
}

// 5. 휴가 일정 관련 유틸
function collectStrings(value, result = [], depth = 0) {
  if (depth > 10 || value == null) return result;

  if (
    typeof value === "string" ||
    typeof value === "number" ||
    typeof value === "boolean"
  ) {
    result.push(String(value));
    return result;
  }

  if (Array.isArray(value)) {
    for (const v of value) {
      collectStrings(v, result, depth + 1);
    }
    return result;
  }

  if (typeof value === "object") {
    for (const v of Object.values(value)) {
      collectStrings(v, result, depth + 1);
    }
  }

  return result;
}

function itemToSearchText(item) {
  return collectStrings(item?.json ?? item).join(" ");
}

function isVacationText(text) {
  const t = norm(text);

  return [
    "휴가",
    "연차",
    "반차",
    "오전반차",
    "오후반차",
    "공가",
    "휴무",
    "휴일",
    "공휴일",
    "명절",
    "안식월",
    "sabbatical",
    "leave",
    "vacation",
    "pto",
    "dayoff",
    "off"
  ].some(keyword => t.includes(norm(keyword)));
}

function extractAllYmds(text) {
  return String(text ?? "").match(/\d{4}-\d{2}-\d{2}/g) || [];
}

function extractYmd(str) {
  const m = String(str ?? "").match(/\d{4}-\d{2}-\d{2}/);
  return m ? m[0] : "";
}

function extractDateRanges(item) {
  const obj = item?.json ?? item;
  const ranges = [];
  const seen = new Set();

  function pushRange(key, start, end) {
    const s = extractYmd(start);
    const e = extractYmd(end || start);
    if (!s) return;

    const uniq = `${key}|${s}|${e}`;
    if (seen.has(uniq)) return;
    seen.add(uniq);

    ranges.push({
      key,
      start: s,
      end: e || s
    });
  }

  function walk(value, path = "root", depth = 0) {
    if (depth > 8 || value == null) return;

    if (typeof value === "string") {
      const ymds = extractAllYmds(value);
      if (ymds.length === 1) {
        pushRange(path, ymds[0], ymds[0]);
      } else if (ymds.length >= 2) {
        pushRange(path, ymds[0], ymds[1]);
      }
      return;
    }

    if (typeof value === "number" || typeof value === "boolean") {
      return;
    }

    if (Array.isArray(value)) {
      value.forEach((v, idx) => walk(v, `${path}[${idx}]`, depth + 1));
      return;
    }

    if (typeof value === "object") {
      if ("start" in value && extractYmd(value.start)) {
        pushRange(`${path}.startEnd`, value.start, value.end || value.start);
      }

      if ("date" in value && value.date && typeof value.date === "object" && extractYmd(value.date.start)) {
        pushRange(`${path}.date`, value.date.start, value.date.end || value.date.start);
      }

      if (
        "formula" in value &&
        value.formula &&
        typeof value.formula === "object" &&
        value.formula.type === "date" &&
        value.formula.date &&
        extractYmd(value.formula.date.start)
      ) {
        pushRange(`${path}.formula.date`, value.formula.date.start, value.formula.date.end || value.formula.date.start);
      }

      for (const [k, v] of Object.entries(value)) {
        walk(v, `${path}.${k}`, depth + 1);
      }
    }
  }

  walk(obj);

  return ranges;
}

function isTodayIncluded(start, end, today) {
  if (!start) return false;
  const realEnd = end || start;
  return start <= today && today <= realEnd;
}

// 6. 오늘 날짜가 포함된 휴가/안식월 일정만 추출
const todayVacationItems = vacationItems.filter(item => {
  const text = itemToSearchText(item);

  if (!isVacationText(text)) return false;

  const ranges = extractDateRanges(item);
  if (ranges.length === 0) return false;

  return ranges.some(r => isTodayIncluded(r.start, r.end, todayKST));
});

// 7. 오늘 휴가/안식월인 사용자 추출
const vacationUsers = allUsers.filter(user => {
  return todayVacationItems.some(item => {
    const text = itemToSearchText(item);

    return (
      norm(text).includes(norm(user.name)) ||
      norm(text).includes(norm(user.email))
    );
  });
});

const vacationUserEmails = new Set(vacationUsers.map(u => u.email));
const activeUsers = allUsers.filter(u => !vacationUserEmails.has(u.email));

// 8. 이슈 목록
const pages = issueItems
  .map(item => item?.json)
  .filter(page =>
    page &&
    typeof page === "object" &&
    page.properties &&
    typeof page.properties === "object"
  );

const targetIssues = pages.filter(page => {
  const statusName = getStatus(page);
  const typeName = getIssueType(page);

  const isRegistered = norm(statusName) === norm("등록");
  const isTargetType = ["제안", "버그", "문의"].some(
    t => norm(typeName) === norm(t)
  );

  return isRegistered && isTargetType;
});

// 9. 메시지용 텍스트 생성
const activeUserNames = activeUsers.map(u => u.name).join(", ");
const activeUserMentionText = activeUsers.map(u => `<at>${u.name}</at>`).join(", ");
const activeUserEntities = activeUsers.map(u => ({
  type: "mention",
  text: `<at>${u.name}</at>`,
  mentioned: { id: u.email, name: u.name }
}));

let teamsText = "";
let teamsEntities = [];
let issuesContent = "";

let cardTitle = "";
let cardIntro = "";
let cardDetails = "";
let cardFooter = "";
let cardFooterColor = "Default";

// 모바일/요약용 텍스트(멘션 태그 없이)
let summaryText = "";

if (targetIssues.length === 0) {
  teamsText = "";
  teamsEntities = [];
  issuesContent = "";

  cardTitle = `${checkLabel} - 이슈 없음`;
  cardIntro = "현재 확인이 필요한 이슈가 없습니다.";
  cardDetails = "";
  cardFooter = "";
  cardFooterColor = "Good";

  summaryText = `${checkLabel} - 이슈 없음`;
} else {
  teamsText = activeUserMentionText;
  teamsEntities = activeUserEntities;

  const issuesList = targetIssues.map((page) => {
    const title = getTitle(page) || "제목 없음";
    const type = getIssueType(page) || "유형 없음";
    return `[${type}] ${title}`;
  });

  issuesContent = issuesList.join("\n");

  // 제목은 짧게
  if (activeUsers.length > 0) {
    cardTitle = `${checkLabel} - ${teamsText} ${targetIssues.length}건`;
    summaryText = `${checkLabel} - ${activeUserNames} ${targetIssues.length}건`;
  } else {
    cardTitle = `${checkLabel} - 확인 ${targetIssues.length}건`;
    summaryText = `${checkLabel} - 확인 ${targetIssues.length}건`;
  }

  cardIntro = `[${dateString}] 확인이 필요한 이슈가 ${targetIssues.length}건 있습니다.`;
  cardDetails = issuesContent;
  cardFooter = "내용 확인 후 검토 부탁드립니다! 🚀";
  cardFooterColor = "Attention";
}

// 10. 반환
return [{
  json: {
    teamsText,
    teamsEntities,
    issuesContent,
    issueCount: targetIssues.length,
    date: dateString,
    checkLabel,
    cardTitle,
    cardIntro,
    cardDetails,
    cardFooter,
    cardFooterColor,
    summaryText,
    debug: {
      todayKST,
      hourKST,
      checkLabel,
      issueSourceCount: issueItems.length,
      vacationSourceCount: vacationItems.length,
      todayVacationCount: todayVacationItems.length,
      vacationUsers: vacationUsers.map(u => ({
        name: u.name,
        email: u.email
      })),
      activeUsers: activeUsers.map(u => ({
        name: u.name,
        email: u.email
      })),
      matchedTitles: targetIssues.map(page => getTitle(page)),
      sampleStatusType: pages.slice(0, 5).map(page => ({
        title: getTitle(page),
        status: getStatus(page),
        type: getIssueType(page)
      }))
    }
  }
}];

const source = $input.first()?.json ?? {};
const now = new Date();
const parts = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Seoul',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  weekday: 'short'
}).formatToParts(now);

const year = parts.find((p) => p.type === 'year')?.value;
const month = parts.find((p) => p.type === 'month')?.value;
const day = parts.find((p) => p.type === 'day')?.value;
const weekdayName = parts.find((p) => p.type === 'weekday')?.value;

if (!year || !month || !day || !weekdayName) {
  throw new Error('Failed to resolve current date in Asia/Seoul.');
}

const todayInt = Number(`${year}${month}${day}`);
const todayDate = `${year}-${month}-${day}`;
const todayMMDD = `${month}${day}`;
const isWeekend = ['Sat', 'Sun'].includes(weekdayName);

return [{
  json: {
    ...source,
    Year: Number(year),
    Month: Number(month),
    Day: Number(day),
    WeekdayName: weekdayName,
    IsWeekend: isWeekend,
    DefaultIsHoliday: isWeekend,
    DefaultHolidayName: isWeekend ? '\uC8FC\uB9D0' : '\uD3C9\uC77C',
    todayInt,
    todayDate,
    todayMMDD
  }
}];
